function say(kind){if(game.s.active===null||game.time-lastSpeech<5)return;const pool=voice[game.s.active][kind];if(!pool)return;lastSpeech=game.time;const text=pool[Math.floor(Math.random()*pool.length)];$('#hero-speech').textContent=text;$('#hero-speech').hidden=false;speechUntil=game.time+3.3;}
function drainEvents(){let learned='';for(const ev of game.events.splice(0)){if(['damage','attack','skill','kill','heal','dash','enemyAttack','loot'].includes(ev.type))fx.push({...ev,age:0});if(ev.type==='attack')lastAttack=game.time;if(ev.type==='boss')say('boss');if(ev.type==='skill'&&Math.random()<.3)say('skill');if(ev.type==='loot'){if(game.h.autoEquip!==true&&!Object.values(game.h.equip).includes(ev.item))lootQueue.push({hero:game.s.active,key:ev.item});lootQueue=lootQueue.slice(-12);sprite(ev.sheet,ev.cell).catch(()=>{});if(Math.random()<.55)say('loot');}if(ev.type==='down')say('down');if(ev.type==='clear')say('clear');if(ev.type==='promote'){say('job');toast(ev.name+' 전직 완료');portraitKey='';}if(ev.type==='skillLearn')learned=ev.name;if(ev.type==='cycle')toast(ev.cycle+'회차 시작 · 더 강한 적이 기다립니다.');if(ev.type==='level')toast('레벨 '+ev.level+' 달성');if(ev.type==='skill'&&ev.ultimate){$('#cast-banner').textContent='ULTIMATE · '+ev.name;$('#cast-banner').hidden=false;castUntil=game.time+1.8;}}if(learned)toast('새 스킬 습득 · '+learned);fx=fx.slice(-220);}
